// A quorum write across 3 regions waits for the slowest
// replica actually required to reach the quorum size
int[] regionLatencyMs = { 5, 40, 140 };
Arrays.sort(regionLatencyMs);
int quorumSize = 2; // need 2 of 3 to acknowledge
int writeLatency = regionLatencyMs[quorumSize - 1]; // 40ms
// Requiring all 3 (quorumSize = 3) would instead cost 140ms,
// bounded by the single farthest region every time

